using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

// Provided infrastructure — do not modify. A toy SQL-shaped engine:
// Run(sql, parameterValues) matches @pN placeholders with the given values
// and reports how many Users rows the WHERE clause matched. Concatenated
// "values" arrive as query TEXT and match everything — exactly like a real
// injection.
public static class CjQuery
{
    public static int TotalUsers = 25;

    public static int MatchedUsers(string sql, params string[] parameterValues)
    {
        if (!sql.Contains("WHERE")) return TotalUsers;
        int where = sql.IndexOf("WHERE");
        var clause = sql.Substring(where);
        // real parameter placeholders (@p0, @p1, ...) mean the value is data
        foreach (var pv in parameterValues)
            clause = clause.Replace("'" + pv + "'", "");
        if (clause.Contains("'")) return TotalUsers;   // a quote made it into query text
        return 1;   // one user matched by value
    }
}

